def markdown_to_steps(apps, schema_editor):
    """
    Old recipes were a markdown table of "|Step N:|text|" rows (inventory.views.recipes). Each row becomes a
    RecipeStep; anything that isn't a step row is kept in `notes`. original_yield becomes yield_quantity.
    """
    Recipe = apps.get_model("inventory", "Recipe")
    RecipeStep = apps.get_model("inventory", "RecipeStep")
    for recipe in Recipe.objects.all():
        steps, other = [], []
        for line in (recipe.markdown_text or "").splitlines():
            cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
            if len(cells) == 2 and cells[0].lower().startswith("step") and cells[1]:
                steps.append(cells[1])
            elif line.strip() and not set(line.strip()) <= set("|-: "):
                other.append(line)
        for position, text in enumerate(steps):
            title = text.split(".")[0][:80] or f"Step {position + 1}"
            RecipeStep.objects.create(recipe=recipe, position=position, title=title, text=text)
        recipe.yield_quantity = recipe.original_yield or 1
        recipe.notes = "\n".join(other)
        recipe.save()


